parameters.functionScript:
// A non-empty connected Items array wins over the Static Data samples, so the
// entry shows what it is the moment it is placed and steps aside the instant real
// data is wired in. Every input is guarded: an unconnected input is undefined, and
// a Static Data node hands over a collection rather than a bare array.
const asArray = (v) => Array.isArray(v) ? v : (v && Array.isArray(v.items) ? v.items : []);
const connected = asArray(Inputs.Items);
Outputs.Items = connected.length > 0 ? connected : asArray(Inputs.Fallback);

if(Inputs.generateColor){
    const palette = Inputs.Colors;
    const text = Inputs.Text;

    function hashCode(str) {
        var hash = 0, i, chr;
        if (str.length === 0) return hash;
        for (i = 0; i < str.length; i++) {
            chr = str.charCodeAt(i);
            hash = (hash << 5) - hash + chr;
            hash |= 0;
        }
        return hash;
    }

    Outputs.Color = palette[hashCode(text) % palette.length];
} 

else{
    Outputs.Color = Inputs.defaultColor;
}
